function readSaved(key, fallback) {
  try {
    const raw = localStorage.getItem(key)
    return raw ? JSON.parse(raw) : fallback
  } catch {
    return fallback
  }
}

const money = (amount) => new Intl.NumberFormat('en-IN', {
  style: 'currency', currency: 'INR', maximumFractionDigits: 0,
}).format(Number(amount) || 0)
const makeId = (prefix = 'AM') => `${prefix}-${Date.now().toString().slice(-7)}-${Math.floor(Math.random() * 90 + 10)}`
const slugify = (value = '') => String(value).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
const safeDigits = (value = '') => String(value).replace(/\D/g, '')
const slugToCategory = (slug) => CATEGORIES.find((category) => slugify(category) === slug) || ''
const formatDate = (value) => {
  try { return new Intl.DateTimeFormat('en-IN', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) }
  catch { return '—' }
}

function resolveRoute(pathname) {
  const path = pathname.replace(/\/+$/, '') || '/'
  if (path === '/') return { name: 'home' }
  if (path === '/products') return { name: 'products' }
  if (path === '/deals') return { name: 'deals' }
  if (path === '/cart') return { name: 'cart' }
  if (path === '/checkout') return { name: 'checkout' }
  if (path === '/bulk-orders') return { name: 'bulk' }
  if (path === '/about') return { name: 'about' }
  if (path === '/contact') return { name: 'contact' }
  if (path === '/help') return { name: 'help' }
  if (path === '/track-order') return { name: 'track-order' }
  if (path === '/wishlist') return { name: 'wishlist' }
  if (path === '/admin/login') return { name: 'admin-login' }
  if (path === '/admin') return { name: 'admin-overview' }
  if (path === '/admin/products') return { name: 'admin-products' }
  if (path === '/admin/orders') return { name: 'admin-orders' }
  if (path === '/admin/bulk') return { name: 'admin-bulk' }
  if (path === '/admin/settings') return { name: 'admin-settings' }
  const categoryMatch = path.match(/^\/categories\/([^/]+)$/)
  if (categoryMatch) return { name: 'category', slug: categoryMatch[1], category: slugToCategory(categoryMatch[1]) }
  const productMatch = path.match(/^\/products\/([^/]+)$/)
  if (productMatch) return { name: 'product', slug: productMatch[1] }
  const successMatch = path.match(/^\/order-confirmation\/([^/]+)$/)
  if (successMatch) return { name: 'order-confirmation', id: successMatch[1] }
  return { name: 'not-found' }
}

function useSimpleRouter() {
  const [url, setUrl] = useState(() => new URL(window.location.href))
  useEffect(() => {
    const onPopState = () => setUrl(new URL(window.location.href))
    window.addEventListener('popstate', onPopState)
    return () => window.removeEventListener('popstate', onPopState)
  }, [])
  const navigate = useCallback((to, options = {}) => {
    const next = new URL(to, window.location.origin)
    if (options.replace) window.history.replaceState({}, '', next)
    else window.history.pushState({}, '', next)
    setUrl(next)
    if (!options.preserveScroll) window.scrollTo({ top: 0, behavior: 'auto' })
  }, [])
  return { url, navigate, route: resolveRoute(url.pathname) }
}

