function Toast({ toast, onClose }) {
  if (!toast) return null
  return <div className={`toast toast-${toast.type || 'success'}`} role="status">{toast.type === 'error' ? <AlertTriangle size={18} /> : <CheckCircle2 size={18} />}<span>{toast.message}</span><button onClick={onClose} aria-label="Dismiss message"><X size={15} /></button></div>
}

function Badge({ children, tone = 'neutral' }) { return <span className={`badge badge-${tone}`}>{children}</span> }

function ProductCard({ product, onOpen, onAdd, onBulk, onCategory, wished, onWish }) {
  const percent = product.mrp > product.price ? Math.round((product.mrp - product.price) / product.mrp * 100) : 0
  return (
    <article className="product-card">
      <div className="product-card-media">
        <button className="product-visual-trigger" onClick={() => onOpen(product)} aria-label={`View ${product.name}`}><ProductVisual product={product} /></button>
        {percent > 0 && <span className="discount-ribbon">-{percent}%</span>}
        {product.popular && <span className="product-flag">Bestseller</span>}
        <button className={`wishlist-button ${wished ? 'wish-active' : ''}`} onClick={() => onWish(product.id)} aria-label={wished ? 'Remove from wishlist' : 'Add to wishlist'}><Heart size={17} fill={wished ? 'currentColor' : 'none'} /></button>
      </div>
      <div className="product-card-content">
        <button className="product-category-link" onClick={() => onCategory ? onCategory(product.category) : onOpen(product)}>{product.category}</button>
        <button className="product-name-link" onClick={() => onOpen(product)}>{product.name}</button>
        <div className="product-unit-line">{product.unit} <span>·</span> <span className={product.stock > 0 ? 'stock-text' : 'out-text'}>{product.stock > 0 ? 'In stock' : 'Out of stock'}</span></div>
        <div className="product-price-line"><strong>{money(product.price)}</strong>{product.mrp > product.price && <del>{money(product.mrp)}</del>}</div>
        <div className="save-line">{percent > 0 ? `Save ${money(product.mrp - product.price)}` : 'Everyday value'}</div>
        <div className="card-actions"><button className="button button-primary add-to-cart" disabled={Number(product.stock) <= 0} onClick={() => onAdd(product)}><Plus size={15} /> {product.stock <= 0 ? 'Out of stock' : 'Add to cart'}</button><button className="button button-icon-outline" onClick={() => onBulk(product)} aria-label={`Request bulk price for ${product.name}`} title="Ask for bulk price"><Handshake size={17} /></button></div>
      </div>
    </article>
  )
}

